const input = $input.first().json;

let code = input.codeconcat || input.code || "";

if ((!code || code.trim() === "" || code.includes("// no code")) && Array.isArray(input.files)) {
  code = input.files
    .map(f => `// FILE: ${f.path || f.name || "unknown"}\n${f.content || ""}`)
    .join("\n\n");
}

if (!input.task_id && !input.taskid) {
  return [{
    json: {
      valid: false,
      error: "Champ 'task_id' manquant",
      task_id: "unknown",
      language: input.language || "javascript"
    }
  }];
}

if (!input.language) {
  return [{
    json: {
      valid: false,
      error: "Champ 'language' manquant",
      task_id: input.task_id || input.taskid,
      language: "unknown"
    }
  }];
}

if (!code || code.trim() === "" || code.trim() === "// no code") {
  return [{
    json: {
      valid: false,
      error: "Champ 'code' manquant ou vide",
      task_id: input.task_id || input.taskid,
      language: input.language
    }
  }];
}

return [{
  json: {
    ...input,
    task_id: input.task_id || input.taskid,
    code,
    valid: true
  }
}];

const raw = $input.first().json;

let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object' && Object.keys(rawBody).length > 0) {
    data = rawBody;
  }
}

return [{ json: data }];

const input = $input.first().json;

// Sécurité : limiter la taille du code analysé (50KB max)
let code = input.code || input.codeconcat || "";
const MAX_SIZE = 50000;
if (code.length > MAX_SIZE) {
  code = code.substring(0, MAX_SIZE) + '\n// ... [tronqué]';
}

const task_id  = input.task_id  || "unknown";
const language = input.language || "javascript";

if (input.valid === false) {
  return [{ json: {
    agent: "Agent Code Review", task_id, status: "ERROR",
    global_score: 0, approved_for_pipeline: false, language,
    critical_issues: [{ severity: "high", category: "validation",
      file: "?", description: input.error || "Validation échouée",
      impact: "Pipeline ne peut pas continuer",
      fix: "Vérifier le payload envoyé à l'agent" }],
    warnings: [], recommendations: ["Corriger le payload d'entrée"],
    summary: input.error || "Payload invalide",
    dimensions: { security: { score: 0 }, quality: { score: 0 } },
    timestamp: new Date().toISOString()
  }}];
}

const issues = [];

// ── SÉCURITÉ OWASP ─────────────────────────────────────────────────────────

// A02 — Secrets hardcodés
if (/password\s*[:=]\s*['"][^'"]{3,}['"]/i.test(code))
  issues.push({ severity:"high", category:"security", file:"?",
    description:"Secret hardcodé : password en clair",
    impact:"Exposition des credentials si le code est partagé ou versionné",
    fix:"Utiliser process.env.PASSWORD à la place" });

if (/api[_-]?key\s*[:=]\s*['"][^'"]{6,}['"]/i.test(code))
  issues.push({ severity:"high", category:"security", file:"?",
    description:"API Key hardcodée (OWASP A02:2021)",
    impact:"Clé exposée dans le code source / dépôt Git",
    fix:"const API_KEY = process.env.API_KEY;" });

if (/(SECRET|TOKEN|PWD)\s*=\s*['"][^'"]{4,}['"]/i.test(code) && !/process\.env/.test(code))
  issues.push({ severity:"high", category:"security", file:"?",
    description:"Constante sensible hardcodée",
    impact:"Données sensibles exposées dans le code",
    fix:"Déplacer dans les variables d'environnement (.env)" });

// A03 — Injection
if (/\beval\s*\(/.test(code))
  issues.push({ severity:"high", category:"security", file:"?",
    description:"Code Injection : eval() détecté (OWASP A03:2021)",
    impact:"Exécution de code arbitraire possible",
    fix:"Supprimer eval() — utiliser JSON.parse() si parsing JSON" });

if (/innerHTML\s*=[^=]/i.test(code))
  issues.push({ severity:"high", category:"security", file:"frontend/app.js",
    description:"XSS potentiel : innerHTML avec données non échappées (OWASP A03:2021)",
    impact:"Injection de scripts malveillants côté client",
    fix:"Utiliser textContent ou escapeHtml() avant innerHTML" });

// A07 — Auth cassée
if (/jwt\.verify\s*\([^,]+,\s*['"]none['"]/i.test(code))
  issues.push({ severity:"high", category:"security", file:"?",
    description:"JWT algorithme 'none' (OWASP A07:2021)",
    impact:"Token JWT non vérifié — authentification contournable",
    fix:"Spécifier un algorithme : { algorithms: ['HS256'] }" });

// ── QUALITÉ FONCTIONNELLE ──────────────────────────────────────────────────

// Store non utilisé
if (/const store\s*=/.test(code) && /res\.(json|send)\s*\(\s*\[\s*\]\s*\)/i.test(code))
  issues.push({ severity:"high", category:"quality", file:"server.js",
    description:"res.json([]) statique — le store n'est pas lu",
    impact:"Les données créées ne sont jamais retournées",
    fix:"res.json(store.items) au lieu de res.json([])" });

// express.static absent avec frontend
if (code.includes('frontend') && !code.includes('express.static'))
  issues.push({ severity:"medium", category:"quality", file:"server.js",
    description:"express.static manquant alors que frontend/ est généré",
    impact:"Le frontend HTML/CSS/JS ne sera pas servi par le serveur",
    fix:"app.use(express.static(path.join(__dirname, 'frontend')))" });

// PORT hardcodé
if (/app\.listen\s*\(\s*[0-9]{4,5}[^)]/.test(code) && !code.includes('process.env.PORT'))
  issues.push({ severity:"medium", category:"quality", file:"server.js",
    description:"PORT hardcodé — non configurable par environnement",
    impact:"Impossible de changer le port sans modifier le code",
    fix:"const PORT = process.env.PORT || 3000;" });

// Endpoints sans try/catch
const epCount    = (code.match(/app\.(get|post|put|delete|patch)\s*\(/gi) || []).length;
const tryCount   = (code.match(/try\s*\{/g) || []).length;
if (epCount > 0 && tryCount < Math.floor(epCount / 2))
  issues.push({ severity:"medium", category:"quality", file:"server.js",
    description:`${epCount} endpoints mais seulement ${tryCount} try/catch`,
    impact:"Erreurs non gérées → crash du serveur sur exception",
    fix:"Entourer chaque endpoint de try { ... } catch(err) { res.status(500)... }" });

// try/catch imbriqués (code corrompu)
if ((code.match(/try\s*\{[\s\S]{0,50}try\s*\{/g) || []).length > 0)
  issues.push({ severity:"medium", category:"quality", file:"server.js",
    description:"try/catch imbriqués détectés — signe de code mal généré",
    impact:"Gestion d'erreurs confuse, comportement imprévisible",
    fix:"Supprimer les try/catch dupliqués" });

// Console.log sensibles
const sensitiveLogs = (code.match(/console\.(log|info)\s*\([^)]*(?:password|token|secret|key|auth)/gi) || []).length;
if (sensitiveLogs > 0)
  issues.push({ severity:"medium", category:"security", file:"?",
    description:`${sensitiveLogs} console.log avec données potentiellement sensibles`,
    impact:"Fuite d'informations dans les logs serveur",
    fix:"Supprimer ou masquer les données sensibles dans les logs" });

// Console.log debug excessifs
const allLogs = (code.match(/console\.(log|debug)/g) || []).length;
if (allLogs >= 5)
  issues.push({ severity:"low", category:"quality", file:"?",
    description:`${allLogs} console.log de debug — à nettoyer avant production`,
    impact:"Logs verbeux en production, légère dégradation perfo",
    fix:"Supprimer ou conditionner avec if (process.env.NODE_ENV !== 'production')" });

// ── SCORE ──────────────────────────────────────────────────────────────────
const highCount   = issues.filter(i => i.severity === "high").length;
const mediumCount = issues.filter(i => i.severity === "medium").length;
const lowCount    = issues.filter(i => i.severity === "low").length;

let score = 100 - (highCount * 25) - (mediumCount * 10) - (lowCount * 3);
score = Math.max(0, Math.min(100, score));

const secIssues = issues.filter(i => i.category === "security" && i.severity === "high").length;
const secScore  = Math.max(0, 100 - (secIssues * 35));
const approved  = highCount === 0 && score >= 55;
const status    = highCount > 0 ? "FAIL" : (mediumCount >= 3 ? "WARN" : "PASS");

return [{ json: {
  agent: "Agent Code Review",
  task_id, status,
  global_score: score,
  approved_for_pipeline: status !== "FAIL",
  language,
  critical_issues: issues.filter(i => i.severity === "high"),
  warnings:        issues.filter(i => i.severity !== "high"),
  recommendations: [
    ...(highCount   > 0 ? [`Corriger les ${highCount} issue(s) HIGH en priorité`] : []),
    ...(mediumCount > 0 ? [`Vérifier les ${mediumCount} issue(s) MEDIUM`] : []),
    ...(score >= 80     ? ["Code de bonne qualité — prêt pour la suite"] : [])
  ],
  summary: status === "FAIL"
    ? `${highCount} issue(s) critique(s) bloquante(s)`
    : `Code ${score >= 80 ? "de qualité" : "acceptable"} — ${issues.length} issue(s)`,
  dimensions: {
    security: { score: secScore },
    quality:  { score: score }
  },
  timestamp: new Date().toISOString()
}}];
